261	  function renumber(grid){
262	    grid.querySelectorAll('.item .num').forEach(function(el, i){ el.textContent = i + 1; });
263	    var title = grid.previousElementSibling;
264	    if (title && title.classList.contains('section-title')) {
265	      var countEl = title.querySelector('.count');
