271	    var layout = {};
272	    document.querySelectorAll('.grid').forEach(function(grid){
273	      layout[grid.dataset.section] = Array.prototype.map.call(grid.querySelectorAll('.item'), function(it){ return it.dataset.url; });
274	    });
275	    localStorage.setItem(LAYOUT_KEY, JSON.stringify(layout));
276	    // 清掉2026-07-20版之前的舊格式（每組各自存一個key），避免新舊格式打架
277	    document.querySelectorAll('.grid').forEach(function(grid){
278	      localStorage.removeItem('coach888_order_' + grid.dataset.section);
279	    });
