282	  function loadLayout(){
283	    var raw = localStorage.getItem(LAYOUT_KEY);
284	    if (raw) {
285	      try { return JSON.parse(raw); } catch(e){}
286	    }
287	    // 相容舊版：只支援組內排序、每組各自一個key，讀出來當初始佈局
288	    var legacy = {}, found = false;
289	    document.querySelectorAll('.grid').forEach(function(grid){
290	      var old = localStorage.getItem('coach888_order_' + grid.dataset.section);
291	      if (old) {
292	        try { legacy[grid.dataset.section] = JSON.parse(old); found = true; } catch(e){}
293	      }
294	    });
295	    return found ? legacy : null;
296	  }
