414	      '<div class="url">' + url.replace(/</g, '&lt;') + '</div>' +
415	      '<div class="badge star" contenteditable="true" spellcheck="false">' + badge.replace(/</g, '&lt;') + '</div>' +
416	      '<span class="item-del" title="刪除這個項目">✕</span>';
417	    grid.appendChild(item);
