425	  function wireSectionBlock(block){
426	    var title = block.querySelector('.section-title');
427	    var grid = block.querySelector('.grid');
428	    var arrow = title.querySelector('.toggle-arrow');
429	    arrow.addEventListener('click', function(){
430	      block.classList.toggle('collapsed');
431	      saveCollapse();
432	    });
433	    var delBtn = title.querySelector('.section-del');
434	    delBtn.addEventListener('click', function(){
435	      var name = title.querySelector('.title-text').textContent.trim();
436	      if (!confirm('確定要刪除整個「' + name + '」分類嗎？裡面所有項目都會一起消失。')) return;
437	      block.remove();
438	      renumberSections();
439	      saveLayout();
440	      saveTitles();
441	      toast('已刪除「' + name + '」分類');
442	    });
443	    var titleText = title.querySelector('.title-text');
444	    bindEditable(titleText, saveTitles);
445	    var addBtn = block.querySelector('.btn-add-item');
446	    addBtn.addEventListener('click', function(){ addItem(grid); });
447	  }
