449	  function addSection(){
450	    var name = prompt('新分類的標題？');
451	    if (name === null || name.trim() === '') return;
452	    name = name.trim();
453	    var key = 'custom' + Date.now();
454	
455	    var block = document.createElement('div');
456	    block.className = 'section-block';
457	    block.innerHTML =
458	      '<div class="section-title" data-section="' + key + '">' +
459	        '<span class="toggle-arrow" title="收合/展開">▼</span>' +
460	        '<span class="idx">、</span>' +
461	        '<span class="title-text" contenteditable="true" spellcheck="false">' + name.replace(/</g, '&lt;') + '</span> ' +
462	        '<span class="count">0項</span>' +
463	        '<span class="section-del" title="刪除整個分類">🗑</span>' +
464	      '</div>' +
465	      '<div class="grid" data-section="' + key + '"></div>' +
466	      '<button class="btn-add-item" data-section="' + key + '">+ 新增項目</button>';
467	    document.querySelector('.wrap').appendChild(block);
468	    wireSectionBlock(block);
469	    renumberSections();
470	    saveTitles();
471	    toast('已新增「' + name + '」分類，接著可以按「+ 新增項目」加內容');
472	  }
473	
474	  function applyLayout(){
475	    var layout = loadLayout();
476	    if (!layout) return;
477	    var allItems = {};
478	    document.querySelectorAll('.item').forEach(function(it){ allItems[it.dataset.url] = it; });
479	    document.querySelectorAll('.grid').forEach(function(grid){
480	      var ids = layout[grid.dataset.section];
481	      if (!ids) return;
482	      ids.forEach(function(id){
483	        if (allItems[id]) grid.appendChild(allItems[id]);
484	      });
485	    });
486	  }
