488	  function getDragAfterElement(grid, y){
489	    var els = Array.prototype.slice.call(grid.querySelectorAll('.item:not(.dragging)'));
490	    return els.reduce(function(closest, child){
491	      var box = child.getBoundingClientRect();
492	      var offset = y - box.top - box.height / 2;
493	      if (offset < 0 && offset > closest.offset) {
494	        return { offset: offset, element: child };
495	      }
496	      return closest;
497	    }, { offset: -Infinity, element: null }).element;
498	  }
499	
500	  // 2026-07-20 改用滑鼠事件手刻拖曳（不用 HTML5 原生 draggable API）：
501	  // .item 內部有 <a class="name" href="..."> 連結，瀏覽器對連結元素有自己的
502	  // 原生拖曳行為，跟外層 draggable="true" 互相打架，導致放開時被瀏覽器判定
503	  // 為無效拖放而彈回原位（教練實測回報「都會被打回原來的位置」）。改成監聽
504	  // drag-handle 的 mousedown/mousemove/mouseup 手動搬移 DOM，完全不觸發原生
505	  // 拖放機制，也就不會有這個衝突。
506	  var dragEl = null;
507	  var sourceGrid = null;
508	
509	  function onMouseMove(e){
510	    if (!dragEl) return;
511	    var el = document.elementFromPoint(e.clientX, e.clientY);
512	    var targetGrid = el ? el.closest('.grid') : null;
513	    if (!targetGrid) return;
514	    var afterEl = getDragAfterElement(targetGrid, e.clientY);
515	    if (afterEl == null) {
516	      targetGrid.appendChild(dragEl);
517	    } else if (afterEl !== dragEl) {
518	      targetGrid.insertBefore(dragEl, afterEl);
519	    }
520	  }
521	
522	  function onMouseUp(){
523	    if (!dragEl) return;
524	    dragEl.classList.remove('dragging');
525	    var targetGrid = dragEl.closest('.grid');
526	    renumber(sourceGrid);
527	    if (targetGrid !== sourceGrid) renumber(targetGrid);
528	    saveLayout();
529	    dragEl = null;
530	    sourceGrid = null;
531	    document.removeEventListener('mousemove', onMouseMove);
532	    document.removeEventListener('mouseup', onMouseUp);
533	  }
534	
535	  applyLayout();
536	  applyTitles();
537	  applyBadges();
538	  applyCollapse();
539	
540	  var toastEl = document.getElementById('toast');
541	  function toast(msg){
542	    toastEl.textContent = msg;
543	    toastEl.classList.add('show');
544	    setTimeout(function(){ toastEl.classList.remove('show'); }, 2200);
545	  }
546	
547	  document.querySelectorAll('.item').forEach(wireItem);
548	  document.querySelectorAll('.section-block').forEach(wireSectionBlock);
549	
550	  document.querySelectorAll('.grid').forEach(renumber);
551	
552	  document.getElementById('btnAddSection').addEventListener('click', addSection);
553	
554	  document.getElementById('btnCopy').addEventListener('click', function(){
555	    var lines = [];
556	    document.querySelectorAll('.section-title').forEach(function(title, idx){
557	      var grid = document.querySelectorAll('.grid')[idx];
558	      lines.push(title.textContent.trim());
559	      grid.querySelectorAll('.item').forEach(function(item){
560	        var num = item.querySelector('.num').textContent;
561	        var name = item.querySelector('.name').textContent;
562	        var url = item.dataset.url;
563	        var badge = item.querySelector('.badge').textContent.trim();
564	        lines.push('  ' + num + '. ' + name + '  ' + url + '  [' + badge + ']');
565	      });
566	      lines.push('');
567	    });
568	    var text = lines.join('\n');
569	    navigator.clipboard.writeText(text).then(function(){
570	      toast('已複製目前排序，貼給小龍蝦即可固化進正式檔案');
571	    }, function(){
572	      toast('複製失敗，請手動選取畫面上的文字');
573	    });
574	  });
575	})();
