var bulkModeOn = false;

function updateBulkBar(){
  var checked = document.querySelectorAll('.bulk-checkbox:checked').length;
  document.getElementById('bulkCount').textContent = checked;
  document.getElementById('bulkBar').classList.toggle('show', bulkModeOn);
}

function populateBulkSelect(){
  var sel = document.getElementById('bulkTargetSelect');
  sel.innerHTML = '';
  document.querySelectorAll('.section-title').forEach(function(title){
    var opt = document.createElement('option');
    opt.value = title.dataset.section;
    opt.textContent = title.querySelector('.title-text').textContent.trim();
    sel.appendChild(opt);
  });
}

document.getElementById('btnBulkMode').addEventListener('click', function(){
  bulkModeOn = !bulkModeOn;
  document.querySelector('.wrap').classList.toggle('bulk-mode', bulkModeOn);
  this.textContent = bulkModeOn ? '✅ 結束批量搬移' : '☑️ 批量搬移模式';
  if (bulkModeOn) {
    populateBulkSelect();
  } else {
    document.querySelectorAll('.bulk-checkbox:checked').forEach(function(cb){ cb.checked = false; });
    document.querySelectorAll('.item.selected').forEach(function(it){ it.classList.remove('selected'); });
  }
  updateBulkBar();
});

document.getElementById('btnBulkMove').addEventListener('click', function(){
  var targetSection = document.getElementById('bulkTargetSelect').value;
  var targetGrid = document.querySelector('.grid[data-section="' + targetSection + '"]');
  if (!targetGrid) return;
  var checkedBoxes = Array.prototype.slice.call(document.querySelectorAll('.bulk-checkbox:checked'));
  if (checkedBoxes.length === 0) { toast('請先勾選要搬移的項目'); return; }
  var seenSections = {};
  var sourceGrids = [];
  checkedBoxes.forEach(function(cb){
    var item = cb.closest('.item');
    var srcGrid = item.closest('.grid');
    if (!seenSections[srcGrid.dataset.section]) {
      seenSections[srcGrid.dataset.section] = true;
      sourceGrids.push(srcGrid);
    }
    targetGrid.appendChild(item);
    cb.checked = false;
    item.classList.remove('selected');
  });
  sourceGrids.forEach(renumber);
  renumber(targetGrid);
  saveLayout();
  updateBulkBar();
  var targetName = targetGrid.previousElementSibling.querySelector('.title-text').textContent.trim();
  toast('已搬移 ' + checkedBoxes.length + ' 個項目到「' + targetName + '」，記得按上方複製排序貼給AI固化');
});

